ALTER TABLE src_erp.erp_sales_order ADD COLUMN source_type VARCHAR(20) NOT NULL DEFAULT 'MANUAL',ADD COLUMN source_contract_no VARCHAR(32) NULL,ADD COLUMN tax_rate DECIMAL(8,4) DEFAULT 13,ADD COLUMN factory_code VARCHAR(32) NULL,ADD COLUMN ship_to_address VARCHAR(300) NULL,ADD COLUMN credit_status VARCHAR(20) DEFAULT 'UNCHECKED',ADD COLUMN atp_status VARCHAR(20) DEFAULT 'UNCHECKED';
CREATE UNIQUE INDEX uk_erp_order_contract ON src_erp.erp_sales_order(source_contract_no);
CREATE TABLE IF NOT EXISTS src_erp.erp_sales_order_change(id BIGINT AUTO_INCREMENT PRIMARY KEY,sales_order_id BIGINT NOT NULL,change_type VARCHAR(16) NOT NULL,reason VARCHAR(500) NOT NULL,before_json JSON,after_json JSON,operator VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS src_erp.erp_customer_credit(id BIGINT AUTO_INCREMENT PRIMARY KEY,customer_code VARCHAR(32) NOT NULL UNIQUE,credit_limit DECIMAL(18,2) DEFAULT 0,used_amount DECIMAL(18,2) DEFAULT 0,overdue_amount DECIMAL(18,2) DEFAULT 0,payment_days INT DEFAULT 30,risk_level VARCHAR(16) DEFAULT 'LOW',status VARCHAR(16) DEFAULT 'ACTIVE',updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS src_erp.erp_credit_check(id BIGINT AUTO_INCREMENT PRIMARY KEY,sales_order_no VARCHAR(32) NOT NULL,customer_code VARCHAR(32) NOT NULL,order_amount DECIMAL(18,2) NOT NULL,available_credit DECIMAL(18,2) NOT NULL,overdue_amount DECIMAL(18,2) NOT NULL,risk_level VARCHAR(16),result VARCHAR(20) NOT NULL,workflow_instance_id BIGINT,checked_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),KEY idx_credit_order(sales_order_no));
CREATE TABLE IF NOT EXISTS src_erp.erp_supply_snapshot(id BIGINT AUTO_INCREMENT PRIMARY KEY,material_code VARCHAR(32) NOT NULL,factory_code VARCHAR(32) NOT NULL,supply_date DATE NOT NULL,available_stock DECIMAL(18,4) DEFAULT 0,confirmed_purchase DECIMAL(18,4) DEFAULT 0,planned_production DECIMAL(18,4) DEFAULT 0,allocated_demand DECIMAL(18,4) DEFAULT 0,UNIQUE KEY uk_supply(material_code,factory_code,supply_date));
CREATE TABLE IF NOT EXISTS src_erp.erp_atp_snapshot(id BIGINT AUTO_INCREMENT PRIMARY KEY,sales_order_no VARCHAR(32) NOT NULL,line_no INT NOT NULL,material_code VARCHAR(32) NOT NULL,requested_qty DECIMAL(18,4) NOT NULL,available_qty DECIMAL(18,4) NOT NULL,promised_qty DECIMAL(18,4) NOT NULL,promised_date DATE,result VARCHAR(20) NOT NULL,basis_json JSON,accepted TINYINT(1) DEFAULT 0,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),KEY idx_atp_order(sales_order_no));
